import { CandidateStatus, STATUS_LABELS } from "@/types/candidate";

const badgeClasses: Record<CandidateStatus, string> = {
  received: "bg-slate-100 text-slate-700 ring-slate-200",
  in_progress: "bg-amber-100 text-amber-800 ring-amber-200",
  selected: "bg-emerald-100 text-emerald-800 ring-emerald-200",
  discarded: "bg-rose-100 text-rose-800 ring-rose-200",
};

interface StatusBadgeProps {
  status: CandidateStatus;
}

export function StatusBadge({ status }: StatusBadgeProps) {
  return (
    <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ring-1 ring-inset ${badgeClasses[status]}`}>
      {STATUS_LABELS[status]}
    </span>
  );
}
